command:
// Põe os compêndios SOLTOS dos outros módulos ativos numa pasta com o nome de cada módulo.
// O que já está em alguma pasta não é mexido. Pode rodar de novo depois de instalar um módulo.
const api = game.modules.get("giriarpg-fim-dos-tempos")?.api;
const r = await api?.organizarOutrosModulos();
if (!r) return;
const lista = r.modulos.map((m) => `${m.titulo} (${m.compendios})`).join(", ");
ui.notifications.info(r.compendios ? `${r.compendios} compêndio(s) organizados em pastas: ${lista}.` : "Nenhum compêndio solto de outros módulos.");
